contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedValue, uint256 smallValue) public payable {
        require(address(this).balance >= seedValue);
        require(smallValue < seedValue);
        // fund c so its balance is seedValue
        c.multiplicate{value: seedValue}(address(this));
        // c now has 0 balance; give it Ether via a second multiplicate that succeeds
        // instead, use Command to fund c: send value to c itself with empty data
        c.Command{value: seedValue}(address(c), "");
        uint256 before = address(c).balance;
        bool reverted;
        try c.multiplicate{value: smallValue}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && address(c).balance == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Fund c by having it call itself with empty data via Command (we are Owner).
        c.Command{value: amount}(address(c), "");
        uint256 funded = address(c).balance;
        // As Owner, withdraw must move c's whole balance out.
        c.withdraw();
        assert(funded >= amount && address(c).balance == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
