        // Fund c via Command (we are the Owner) with empty data to self.
        c.Command{value: amount}(address(c), "");
        uint256 funded = address(c).balance;
        // With msg.value == 0 and balance > 0, multiplicate sends the whole balance out.
        bool reverted;
        try c.multiplicate(address(this)) { reverted = false; } catch { reverted = true; }
        assert(funded == amount && !reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

